import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('recordPayment adds a payment to an issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.payments.length, 1);
  assert.deepEqual(paymentResult.value.payments[0], { amount: 50000, date: '2026-10-10' });
  assert.equal(paymentResult.value.status, 'partially_paid');
});

test('recordPayment marks invoice as paid when full amount is paid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');
});

test('recordPayment accepts multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const payment1 = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(payment1.ok, true);
  invoice = payment1.value;

  const payment2 = recordPayment(invoice, { amount: 30000, date: '2026-10-15' });
  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.payments.length, 2);
  assert.equal(payment2.value.payments[0].amount, 50000);
  assert.equal(payment2.value.payments[1].amount, 30000);
});

test('recordPayment reports NOT_ISSUED if invoice is draft', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const result = recordPayment(invoiceResult.value, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports NOT_ISSUED if invoice is paid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  const secondPaymentResult = recordPayment(invoice, { amount: 10000, date: '2026-10-15' });
  assert.deepEqual(secondPaymentResult, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment accepts partially_paid status', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const payment1 = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(payment1.ok, true);
  assert.equal(payment1.value.status, 'partially_paid');

  const payment2 = recordPayment(payment1.value, { amount: 30000, date: '2026-10-15' });
  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'partially_paid');
});

test('recordPayment reports AMOUNT_INVALID for non-positive amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const invalidAmounts = [0, -1000, -100, 1.5, 'abc', null, undefined];
  for (const amount of invalidAmounts) {
    const result = recordPayment(invoice, { amount, date: '2026-10-10' });
    assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' }, `Expected AMOUNT_INVALID for amount: ${JSON.stringify(amount)}`);
  }
});

test('recordPayment reports OVERPAYMENT if amount exceeds balance', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total + 100, date: '2026-10-10' });
  assert.deepEqual(paymentResult, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment allows payment equal to balance due', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');
});

test('recordPayment does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const original = JSON.parse(JSON.stringify(invoice));
  recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(invoice, original);
});

test('balanceDue returns full amount for unpaid issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const due = balanceDue(invoice);
  assert.equal(due, totals.total);
});

test('balanceDue calculates remaining balance after partial payment', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);

  const due = balanceDue(paymentResult.value);
  assert.equal(due, totals.total - 50000);
});

test('balanceDue returns zero for fully paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const paymentResult = recordPayment(invoice, { amount: totals.total, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);

  const due = balanceDue(paymentResult.value);
  assert.equal(due, 0);
});

test('balanceDue with multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);

  const payment1 = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(payment1.ok, true);
  assert.equal(balanceDue(payment1.value), totals.total - 50000);

  const payment2 = recordPayment(payment1.value, { amount: 30000, date: '2026-10-15' });
  assert.equal(payment2.ok, true);
  assert.equal(balanceDue(payment2.value), totals.total - 80000);
});

test('balanceDue for invoice without payments array', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  const invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);
  const due = balanceDue(invoice);
  assert.equal(due, totals.total);
});

test('payment tracking with invoice discounts and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(invoiceResult.ok, true);

  const issuedResult = issueInvoice(invoiceResult.value, []);
  assert.equal(issuedResult.ok, true);
  let invoice = issuedResult.value;

  const totals = require('../src/invoices.js').invoiceTotals(invoice);

  const payment1 = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });
  assert.equal(payment1.ok, true);
  assert.equal(balanceDue(payment1.value), totals.total - 50000);

  const payment2 = recordPayment(payment1.value, { amount: balanceDue(payment1.value), date: '2026-10-15' });
  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'paid');
  assert.equal(balanceDue(payment2.value), 0);
});

